package br.edu.ifms.robotica.servlet;
import java.io.IOException;import java.sql.SQLException;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import br.edu.ifms.robotica.dao.*;import br.edu.ifms.robotica.model.*;import br.edu.ifms.robotica.seguranca.SenhaUtil;
@WebServlet("/alterar-senha") public class AlterarSenhaServlet extends HttpServlet{
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{p.setHeader("Cache-Control","no-store");r.getRequestDispatcher("/WEB-INF/views/public/alterar-senha.jsp").forward(r,p);}
 @Override protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");String tipo=r.getParameter("tipo"),email=r.getParameter("email"),atual=r.getParameter("senhaAtual"),nova=r.getParameter("novaSenha"),confirm=r.getParameter("confirmacao");try{if(nova==null||!nova.equals(confirm))throw new IllegalArgumentException("erro.senha.confirmacao");SenhaUtil.validarNovaSenha(nova);if("estudante".equals(tipo)){Estudante e=new EstudanteDAO().buscarPorEmail(email);if(e==null||!e.isAtivo()||!SenhaUtil.verificar(atual,e.getSenhaHash()))throw new IllegalArgumentException("erro.senha.atual");new EstudanteDAO().atualizarSenha(e.getId(),SenhaUtil.gerarHash(nova));}else if("coordenador".equals(tipo)){Coordenador c=new CoordenadorDAO().buscarPorEmail(email);if(c==null||!c.isAtivo()||!SenhaUtil.verificar(atual,c.getSenhaHash()))throw new IllegalArgumentException("erro.senha.atual");new CoordenadorDAO().atualizarSenha(c.getId(),SenhaUtil.gerarHash(nova));}else throw new IllegalArgumentException("erro.tipo.invalido");p.sendRedirect(r.getContextPath()+"/alterar-senha?sucesso=alteracao");}catch(IllegalArgumentException e){r.setAttribute("erro",e.getMessage());doGet(r,p);}catch(SQLException e){throw new ServletException(e);}}
}
